package com.samsung.android.feature;
import java.util.*;import java.io.*;import org.xmlpull.v1.XmlPullParser;
public final class SemFloatingFeature{
 private static final SemFloatingFeature instance=new SemFloatingFeature();private final Map<String,String> values=new HashMap<>();
 private static boolean hasSamsungBlur(){try{android.view.View.class.getMethod("semSetBlurInfo",Class.forName("android.view.SemBlurInfo"));return true;}catch(ReflectiveOperationException e){return false;}}
 private SemFloatingFeature(){try(InputStream in=getClass().getClassLoader().getResourceAsStream("assets/samsung-floating-feature.xml")){if(in==null)throw new IOException("Donor feature asset unavailable");XmlPullParser p=android.util.Xml.newPullParser();p.setInput(in,"UTF-8");int event;while((event=p.next())!=XmlPullParser.END_DOCUMENT)if(event==XmlPullParser.START_TAG&&p.getName().startsWith("SEC_FLOATING_FEATURE_")){String key=p.getName();values.put(key,p.nextText().trim());}android.util.Log.i("SamsungAirCommandPort","Donor features loaded: "+values.size());}catch(Exception ex){android.util.Log.e("SamsungAirCommandPort","Donor feature load failed",ex);}}
 public static SemFloatingFeature getInstance(){return instance;}public String getString(String k){return getString(k,"");}public String getString(String k,String d){if(k.equals("SEC_FLOATING_FEATURE_COMMON_CONFIG_AI_VERSION")||k.equals("SEC_FLOATING_FEATURE_CAMERA_CONFIG_STRIDE_OCR_VERSION"))return "";String v=values.get(k);return v==null?d:v;}public boolean getBoolean(String k){return getBoolean(k,false);}public boolean getBoolean(String k,boolean d){if(k.equals("SEC_FLOATING_FEATURE_COMMON_SUPPORT_KNOX_DESKTOP")||k.equals("SEC_FLOATING_FEATURE_COMMON_SUPPORT_BIXBY")||k.equals("SEC_FLOATING_FEATURE_FRAMEWORK_SUPPORT_SCREEN_RECORDER"))return false;if(k.equals("SEC_FLOATING_FEATURE_COMMON_DISABLE_NATIVE_AI"))return true;if(k.equals("SEC_FLOATING_FEATURE_GRAPHICS_SUPPORT_3D_SURFACE_TRANSITION_FLAG")&&!hasSamsungBlur())return false;String v=values.get(k);return v==null?d:Boolean.parseBoolean(v);}public int getInt(String k){return getInt(k,-1);}public int getInt(String k,int d){try{return Integer.parseInt(getString(k));}catch(Exception ex){return d;}}
}
